module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or posedge rst)
    if (rst) q <= 8'd0; else q <= q + d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) begin q <= d; $display("%d", d); end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(*) if (d[0]) q = d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  wire a;
  assign a = ~a & d[0];
  always @(posedge clk) q <= {7'd0, a};
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) q <= d / {4'd0, d[3:0]};
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  wire [7:0] w;
  assign #5 w = d;
  always @(posedge clk) q <= w;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) q <= #2 d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  initial q = 8'h00;
  always @(posedge clk) q <= q + d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) if (d === 8'bx) q <= 8'd1; else q <= d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  assign q = d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) begin q <= d end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) q <= d + undeclared_sig;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  wire [7:0] w;
  sub u0(.a(d), .y(w));
  always @(posedge clk) q <= w;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) begin #2 q <= d; end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) begin wait (rst == 1'b0); q <= d; end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always begin
    @(posedge clk) q <= d;
    @(posedge clk) q <= ~d;
  end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or negedge clk) q <= d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) q <= d;
  always @(posedge clk) if (rst) q <= 8'd0;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  reg [7:0] x, n;
  always @(*) begin
    x = d; n = 0;
    while (x != 0) begin x = x >> 1; n = n + 1; end
  end
  always @(posedge clk) q <= n;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  integer i; reg [7:0] acc;
  always @(*) begin
    acc = 0;
    for (i = 0; i < d; i = i + 1) acc = acc + 1;
  end
  always @(posedge clk) q <= acc;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  real r;
  always @(posedge clk) begin r = d * 1.5; q <= r; end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) fork q <= d; join
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) if (rst) force q = 8'd0; else release q;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) q <= $random;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or posedge rst) begin
    q <= d;
    if (rst) q <= 8'd0;
  end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or d[0]) q <= d;
endmodule

module sub(input clk, input [7:0] d);
  reg [7:0] r;
  always @(posedge clk) r <= d;
endmodule
module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  sub u0(.clk(clk), .d(d));
  always @(posedge clk) q <= u0.r;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  class C; int x; endclass
  C obj;
  always @(posedge clk) begin obj = new; q <= d; end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  int da[];
  always @(posedge clk) begin da = new[4]; q <= da.size(); end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  string s;
  always @(posedge clk) begin s = "ab"; q <= s.len(); end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  function automatic [7:0] f(input [7:0] n);
    f = (n <= 1) ? 8'd1 : n * f(n - 1);
  endfunction
  always @(posedge clk) q <= f(d);
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) begin q = d; q <= q + 1; end
endmodule

module top(input clk, input rst, input [7:0] d, output [7:0] q);
  wire [7:0] w;
  always @(posedge clk) w <= d;
  assign q = w;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  task t(input [7:0] a); begin #1 q = a; end endtask
  always @(posedge clk) t(d);
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  event e;
  always @(posedge clk) -> e;
  always @(e) q <= d;
endmodule

module top(input clk, input clk2, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or posedge clk2) q <= d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or posedge rst)
    if (rst) q <= d; else q <= q + 8'd1;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) if (rst) assign q = 8'd0; else deassign q;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(*) forever q = d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  reg [7:0] acc;
  always @(*) begin acc = 0; repeat (d) acc = acc + 1; end
  always @(posedge clk) q <= acc;
endmodule

primitive myand(out, a, b);
  output out; input a, b;
  table
    1 1 : 1;
    0 ? : 0;
    ? 0 : 0;
  endtable
endprimitive
module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  wire w;
  myand g0(w, d[0], d[1]);
  always @(posedge clk) q <= {7'd0, w};
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always q = d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  import "DPI-C" function int cf(int a);
  always @(posedge clk) q <= cf(d);
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  trireg [7:0] t;
  assign t = d[0] ? d : 8'bz;
  always @(posedge clk) q <= t;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk or rst) if (rst) q <= 8'd0; else q <= d;
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) q <= d[d[2:0]:0];
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  always @(posedge clk) begin q <= d; @(negedge clk) q <= ~d; end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  integer fd;
  always @(posedge clk) begin fd = $fopen("x.txt"); q <= d; end
endmodule

module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  time t;
  always @(posedge clk) begin t = $time; q <= t[7:0]; end
endmodule

module sub(input [7:0] a, output [7:0] y);
  assign y = ~a;
endmodule
module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  wire [7:0] w;
  sub u0(.b(d), .y(w));
  always @(posedge clk) q <= w;
endmodule

module sub(input [7:0] a, output [7:0] y);
  assign y = ~a;
endmodule
module top(input clk, input rst, input [7:0] d, output reg [7:0] q);
  wire [7:0] w;
  sub #(.W(8)) u0(.a(d), .y(w));
  always @(posedge clk) q <= w;
endmodule
